"""Fixed generated-probe child source; never import candidate modules on the host."""
from __future__ import annotations

from typing import Any
from . import cumulative_generated_probe_wire_v1 as wire

ADAPTER = '"""Fixed sandbox-only child adapter: emits untrusted values, never expected answers.\n\nRun ONLY inside the separately qualified candidate sandbox/host owner. This is\nnot a standalone safe host runner. The host owner must qualify its actual execution and source boundary.\nHost admission supplies the closed bounded recipe.\n"""\nimport json\nfrom pathlib import Path\nimport sys\n\nPROTOCOL = "cumulative-generated-probe-wire-v1"\nSOURCE = "probe/document.txt"\nJOB = "probe-job"\n\n\ndef emit(slot, value):\n    sys.stdout.write(json.dumps({"protocol": PROTOCOL, "slot": slot, "value": value},\n                                ensure_ascii=True, allow_nan=False, separators=(",", ":")) + "\\n")\n    sys.stdout.flush()\n    expected = ("continue:" + slot + "\\n").encode("ascii")\n    if sys.stdin.buffer.readline(len(expected) + 1) != expected:\n        raise ValueError("Missing exact host continuation")\n\n\ndef main():\n    request = json.loads(Path("/checks/probe-request.json").read_bytes())\n    if type(request) is not dict or set(request) != {"protocol", "template_id", "parameters"} or request["protocol"] != PROTOCOL:\n        raise ValueError("Wrong fixed request")\n    template, params = request["template_id"], request["parameters"]\n    if template not in {"refresh-identity-v1", "refresh-noop-v1", "completed-receipt-replay-v1", "manifest-content-hash-v1"}:\n        raise ValueError("Unknown fixed template")\n    base = Path("/tmp/m2")\n    base.mkdir()\n    root = base / "input"\n    (root / "probe").mkdir(parents=True)\n    text = params.get("initial_text", params.get("text"))\n    if template != "manifest-content-hash-v1":\n        (root / SOURCE).write_bytes(text.encode("utf-8"))\n    # Candidate modules enter only after host-fixed state construction.\n    sys.path.insert(0, "/workspace")\n    from library.catalog.store import Store\n    from library.ingestion.local import import_file\n    from library.ingestion.jobs import JobManager\n    store = Store(base / "library.sqlite")\n    try:\n        if template == "manifest-content-hash-v1":\n            manager = JobManager(store)\n            emit("submitted", manager.submit(JOB, [{"source": SOURCE, "text": text}]))\n            # The host captures the real database through its independently\n            # reviewed path/schema route here; this message is only a boundary.\n            emit("capture_job", {"job_id": JOB, "database": "/tmp/m2/library.sqlite"})\n        else:\n            from library.query.service import Service\n            service = Service(store, root)\n            manager = None\n            token = None\n            if template == "completed-receipt-replay-v1":\n                manager = JobManager(store)\n                emit("submitted", manager.submit(JOB, [{"source": SOURCE, "text": text}]))\n                token = manager.prepare(JOB)\n                emit("prepared", token)\n                receipt = manager.commit(token)\n                emit("original_receipt", receipt)\n                document_id = receipt["documents"][0]["document_id"]\n            else:\n                imported = import_file(store, root, SOURCE)\n                emit("imported", imported)\n                document_id = imported["document"]["document_id"]\n            before = service.lifecycle_show(document_id)\n            emit("before", before)\n            replacement = params.get("replacement_text", text)\n            emit("refresh", service.refresh_document(document_id, before["edit_version"], text=replacement))\n            if manager is not None:\n                emit("replay", manager.commit(token))\n    finally:\n        store.close()\n    emit("finished", {"closed": True})\n\n\nif __name__ == "__main__":\n    main()\n'

def adapter_files(admitted: dict[str, Any], *, released_requirements: tuple[str, ...]) -> dict[str, bytes]:
    """Stage only the fixed code and public request; this does not dispatch."""
    return {"child_driver.py": ADAPTER.encode("utf-8"),
            "probe-request.json": wire.request_bytes(admitted, released_requirements=released_requirements)}
